import unittest
from router.trie import PathRouter

class TestRouter(unittest.TestCase):
    def test_param_match(self):
        r = PathRouter()
        r.add('/users/:id/profile', 'h_user')
        h, p = r.match('/users/42/profile')
        self.assertEqual(h, 'h_user')
        self.assertEqual(p, {'id': '42'})

if __name__ == '__main__': unittest.main()

