class PathRouter:
    def __init__(self):
        self.routes = []

    def add(self, pattern: str, handler) -> None:
        self.routes.append((pattern.strip('/').split('/'), handler))

    def match(self, path: str):
        segments = path.strip('/').split('/')
        for pattern_segs, handler in self.routes:
            if len(pattern_segs) != len(segments): continue
            params = {}
            match = True
            for p_seg, seg in zip(pattern_segs, segments):
                if p_seg.startswith(':'):
                    params[p_seg[1:]] = seg
                elif p_seg != seg:
                    match = False
                    break
            if match:
                return handler, params
        return None, {}
